#!/usr/bin/env python3
"""Generate batch-14-output.json: expand descriptions only, preserve all other fields."""
import json, os

BASE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(BASE, 'batch-14-input.json')
DST = os.path.join(BASE, 'batch-14-output.json')

D = {
    "hangi-oven": "Traditional earth oven of the Māori, in which stones that can withstand great heat — usually river and greywacke stones rather than beach rocks, which can shatter — are heated in a shallow pit until white-hot. Food is laid on the stones in woven baskets, covered with leaves and cloth, and sealed with earth so that the meal steams slowly over several hours. The hāngi has cooked for hui (gatherings), tangihanga (funerals), Waitangi Day and Christmas for generations, and while modern cooks often heat the stones with gas, the principle and the shared meal remain the heart of Māori hospitality.",
    "kundu-drum": "Hourglass hand drum of Papua New Guinea, carved from a single block of light hardwood with a membrane of lizard or snake skin stretched over the open head and held with wax and resin studs, which also tune the drum. It is played with the palm and fingers, its patterns of beats belonging to the village and its ancestors; in the Sepik region the Iatmul associate the drum with the crocodile-creator, and the instrument is used in initiation rites, spirit cults, mourning and the sing-sing gatherings that draw communities together. The kundu is so emblematic that it appears on the national coat of arms, and a fine carved example is a valued heirloom handed down through families.",
    "bilum": "Loop-woven string bag made and worn by women across Papua New Guinea, worked in a continuous spiral of knotless looping that varies in gauge and pattern from region to region. Carried on the head, over the shoulder or around the neck, it holds garden produce, firewood and bush tucker, and in the Highlands it cradles infants, who travel in a woman's bilum until they can walk. Made originally from bush vines and bark fibre and today often from brightly coloured synthetic yarn, a single bilum can take weeks of work and carries meaning in every stitch. Bilums are given as prestigious gifts at marriage, childbirth, feasts and mourning rites, and their designs and colours can mark the wearer's clan and homeland.",
    "trobriand-yam-house": "Ornate storehouse of the Trobriand Islands of Papua New Guinea, raised on posts with a steeply pitched roof and a decorative triangular gable, first described in the anthropological studies of Bronisław Malinowski. The facade is built of wooden slabs tied with coconut-husk fasteners, and yams — the central wealth and prestige crop — are displayed in tight rows through the slits so that the house announces its owner's abundance. Yams are still the symbolic currency of the islands: men cultivate them for their sisters' families under the urigubu obligation, and a man's status is read in the size and beauty of his yam house, which is built to display abundance as the symbolic face of his household.",
    "vanuatu-slit-drum": "Hollowed log drum of Vanuatu, carved from a single tree trunk with a narrow longitudinal slot and open ends, struck with wooden beaters to send a deep, carrying sound across the village and reef. In the northern islands, where the great carved tamtam stand upright before the village, the drums are monuments as much as instruments: many are carved with faces and stand several metres tall as records of chiefs and ancestors. The slit drum calls people to gatherings, announces deaths and ceremonies, keeps the rhythm of dances, and in grade-taking and other graded society rites the number and size of drums a village holds reflects its prestige.",
    "tabua": "Polished sperm whale tooth of Fiji, its base pierced and threaded with a cord of braided sennit, presented with a formal speech as the highest mark of respect and goodwill. The tabua is offered to seal covenants between chiefs, to atone for wrongdoing, to open negotiations or requests that are then rarely refused, and it is kept by the recipient as the living record of the promise. Originally only teeth of beached or stranded whales were available, and later whale-tooth or ivory substitutes were traded in; today the tabua is not sold but exchanged at weddings, birthdays, funerals and chiefly occasions, and its image appears on the Fijian 20-cent coin and in the name of Fiji Airways' Tabua Club.",
    "fijian-masi": "Barkcloth of Fiji, beaten by women from the inner bark of the paper mulberry into broad sheets, which are felted together on a wooden anvil and painted with geometric designs in black, brown and red. Masi is made in working parties for gifts, dress and ceremony: it wraps the body at weddings and funerals, lines the walls of the chiefly house, and the finest decorated pieces are given on occasions of state. The patterns are handed down within clans, whose history the cloth records, and the same barkcloth family is known across the Pacific — masi in Fiji, siapo in Samoa, ngatu in Tonga, kapa in Hawai'i — with each island giving the craft its own style.",
    "fijian-war-club": "Carved club of the Fijian islands, made from the dense wood of the vesi (ironwood) or Pacific casuarina and shaped in a wide range of named forms: the long-bladed ulato, the throwing club, the bulbous totokia with its blunt striking head, and ceremonial clubs inlaid with shell or whalebone. War clubs were the emblem of the Fijian warrior and badges of rank, carried by chiefs as symbols of office and passed down as named trophies and treasures whose owners' histories were remembered. Some were also laid with chiefs in burial, and clubs and whale teeth together formed the ceremonial wealth used to seal alliances and settle the fiercest disputes.",
    "solomon-shell-money": "Traditional currency of the Solomon Islands, made from small discs ground from shell — the red money of Malaita being prized above all — drilled and strung on fibre into long strings and rolled coils. Shell money is still exchanged in bride-price, compensation, feasts and chiefly obligations, its value fixed by the species of shell, the fineness of the grinding and the length of the string. On the Reef Islands and Santa Cruz the most spectacular form is red feather-money: rolls of scarlet feathers from the cardinal honeyeater glued to a fibre base, so prized that only the greatest payments were made with it. The making and the value of these moneys remain part of living island economies.",
    "hawaiian-feather-cloak": "Royal cloak of the Hawaiian chiefs, built on a netted base of olonā fibre and covered with hundreds of thousands of small feathers tied in bundles by a technique called kahekahe. Yellow feathers were taken from the ʻōʻō and mamo — birds whose feathers were pulled by the tens of thousands, contributing to their extinction — and red from the ʻiʻiwi and ʻapapane; Kamehameha I's great cloak is said to contain some 450,000 yellow mamo feathers. The ʻahuʻula was the mark of the highest aliʻi, worn in war and ceremony as a living symbol of chiefly mana and passed down as the supreme heirloom of the kingdom, and surviving examples are counted among the treasures of world museums.",
    "lei-niho-palaoa": "Pendant of the Hawaiian chiefs made from a carved sperm whale tooth suspended on a braid of human hair, worn by men and women of high rank. The hair cord was itself a gift of honour, braided from hair offered by relatives and friends of the wearer, and the whole ornament was kapu — forbidden to anyone beneath the chiefly class. The lei niho palaoa signalled genealogical status and royal favour, and after the arrival of whalers and traders whale teeth and later ivory from walrus tusks were carved in its place, so that the oldest examples, in the richest carving and finest hair-work, are the most treasured heirlooms of Hawaiian families.",
    "hawaiian-pahu": "Standing drum of the Hawaiian islands, carved from a single log of coconut or breadfruit wood and headed with sharkskin or stingray skin stretched and braced with cords. Two kinds are known: the pahu hula, struck with the hands to accompany the hula and chant, and the larger pahu heiau, the sacred temple drum beaten in the heiau to summon the gods and mark the rites of the priests. The drum stands upright and is played with open palms or heel and fingertips, and in the temple it was considered so sacred that only certain priests might sound it, its rhythms regarded as a channel of divine mana.",
    "samoan-siapo": "Barkcloth of Samoa, beaten by women from the inner bark of the paper mulberry into large sheets and decorated with geometric patterns in earth tones, either painted by hand or printed by rubbing colour over carved upeti stencil boards. Siapo is made for wrapping, dress and ceremony — it clothes chiefs, lines meeting houses and forms part of exchange gifts at weddings and funerals — and its designs are owned by families and districts, each pattern marking the cloth as coming from a particular place and lineage. Beating the bark, pasting the sheets together with starch and burnishing the finished cloth are skills passed from mother to daughter, and siapo remains central to Samoan ceremonial life today.",
    "samoan-ie-toga": "Treasured fine mat of Samoa, woven from the thinnest strips of pandanus leaf by senior women and softened, oiled and polished until it gleams. The ʻie toga is the highest form of Samoan wealth, exchanged at weddings, funerals, title-bestowals and political occasions in the ceremonial economy of fa'alavelave, where it is always presented together with fine goods. The oldest mats are given names and genealogies, handed down through generations and counted among the most sacred possessions of the aiga, and a family's honour and standing are measured in the size and age of its store of fine mats.",
    "samoan-tatau-tools": "Set of combs and mallets used in the Samoan tatau, the hand-tapped tattoo applied by a tufuga ta tatau, the tattoo master. A comb of bone, turtle shell or later steel, set with teeth of graduated length, is dipped in soot pigment and struck with a wooden mallet to drive the ink into the skin, line by painful line. The tools and the art are traced by legend to the goddesses Taema and Tilafaiga, who brought the craft from Fiti to Samoa, and the full male pe'a and the female malu are still given with ceremony as marks of dignity and genealogy. A set of tools is the master's most guarded possession, used only within the ritual rules of the practice.",
    "tongan-ngatu": "Barkcloth of Tonga, made by beating the inner bark of the hiapo (paper mulberry) into strips and pasting them together with starch into large sheets, which are then decorated in working parties called koka'anga. Women rub brown and black dyes over carved kupesi rubbing boards to print repeating geometric motifs — chevrons, zigzags and diagonal bands — that carry the patterns of their families and districts. Ngatu is given at weddings, funerals and royal ceremonies, used as floor mats, wall coverings and dance costumes, and the largest ceremonial pieces, some hundreds of metres long, are presented to the king on occasions of state, so that the cloth doubles as a record of the kingdom's ceremonies and its givers.",
    "tahitian-vaa": "Ocean-going sailing canoe of the Tahitians, built as a dugout hull with a single outrigger float lashed on booms and a lateen sail of pandanus matting. The vaʻa was the vessel of the great Polynesian navigators, who read the stars, the swells and the flight of birds to cross the Pacific and settle island after island, and the hull was shaped by carvers working from inherited knowledge of timber and lines. Today the same outrigger canoe races on as a sport in the vaʻa of French Polynesia, where crews paddle long ocean-going canoes in competitions such as the Hawaiki Nui Vaʻa, keeping the voyaging canoe at the centre of Polynesian identity.",
    "marquesan-war-club": "Polished war club of the Marquesas Islands, carved from toa, the dense ironwood, with a long shaft and a flattened, slightly flared head incised with the stylized face of a tiki and other relief designs. The uʻu was the principal weapon of the Marquesan warrior, swung in hand-to-hand combat, but it was equally a work of sculptural art and a badge of rank, kept and treasured as a personal trophy and handed down within families. Some clubs were inlaid with whale tooth or, it is said, with the bone of a fallen enemy, marking the uʻu as both weapon and memorial of its owner.",
    "cook-islands-adze": "Stone-bladed adze of the Cook Islands, ground from fine-grained basalt and lashed to a wooden handle with sennit, used to fell and shape the timber for canoes, houses, war clubs and carvings. The toki was the essential tool of the master craftsman, and the quarries that supplied the prized basalt — above all the great quarry on Mangaia — were controlled by chiefly families and treated as resources of mana. Fine adzes were treasured heirlooms, their lashing and finish a mark of the carver's standing, and the same tool type, its design carried by voyagers across the Pacific, appears in the founding histories of many island traditions.",
    "marshall-stick-chart": "Navigation chart of the Marshall Islands built from pandanus ribs and coconut fibre, with small cowrie shells marking the islands and curved sticks recording the swell and wave patterns of the ocean. Charts come in three kinds: the mattang, which teaches the principles of wave reflection without naming real islands; the meddo, covering a particular group of reefs; and the rebbelib, a large chart of the whole archipelago. Read and memorised by trained navigators before a voyage and then left ashore, the charts encode wave and current knowledge passed down within navigators' families, and the same skill is remembered in the legend of the first navigator who learned to read the sea.",
    "yap-stone-money": "Large circular discs of quarried calcite used as currency on the island of Yap, some measuring several metres across and weighing many tonnes, each with a central hole for carrying on a pole. The rai were quarried on Palau and sailed back to Yap by raft and canoe, and their value was fixed not by size alone but by the difficulty of the voyage and the lives lost in obtaining them — a stone that sank on the way was still counted as wealth because ownership was remembered. Since the discs were too heavy to move, ownership was recorded in memory and passed on orally at marriages, land deals and debts, so that a family's wealth stood in the village's recollection as much as in the stone itself.",
    "palau-storyboard": "Carved wooden panel of Palau recording the myths, histories and village legends of the islands in low-relief figures. The form descends from the painted facade boards of the bai, the great men's meeting house, whose gables carried scenes of the ancestors and of village life, and from the 1930s carvers began to translate those painted narratives into portable low-relief wood. Storyboards show culture heroes, voyages, sea creatures and village quarrels, and they are carved as commemorative gifts, as teaching pieces for the young, and for the market, keeping the island's oral tradition alive in carved form.",
    "nan-madol": "Ruined city of the island of Pohnpei, built on about ninety artificial islets separated by canals, with walls, tombs and terraces raised from great prismatic basalt columns ferried and set into place. It was the ceremonial and political centre of the Saudeleur dynasty, and legend holds that the massive stones were flown and set in place by magic, and that the city fell to the warrior Isokelekel, who came from the east and overthrew the last Saudeleur. Today the site is a World Heritage monument of Micronesia, its canals and basalt ramparts still bearing the names and stories of the chiefs, gods and sorcerers of Pohnpei.",
    "hawaiian-kapa": "Barkcloth of the Hawaiian islands, beaten by women from the inner bark of the wauke, the paper mulberry, on a stone anvil with grooved wooden beaters, and joined and felted into wide sheets. The cloth was printed by stamping with carved bamboo tubes and blocks and with leaves and water-stamped patterns, in colours drawn from earth, charcoal and plants, and the designs were named and passed down within families. Kapa served as clothing, bedding, bandages and swaddling, and in ritual it wrapped the dead and clothed the altars, so that the finest pieces carried the mana of the maker and the household.",
    "tuvaluan-paopao": "Small sailing canoe of the Tuvaluan islands, fitted with a single outrigger float and a triangular sail, used for fishing on the lagoon and the open reef and for the short voyages between the atolls. Built by hand from island timber, with the hull lashed with sennit to the outrigger booms, the paopao is light enough to be beached above the tide and sailed by one or two men. Its design, like that of the canoes of the wider Pacific, was carried by navigational knowledge passed down across the atolls, and the paopao remains both a working fishing craft and a symbol of Tuvaluan seamanship.",
    "kryzdirbyste-cross": "Carved oak wayside crosses of the Lithuanian cross-crafting tradition, one to five metres tall, with small roofs, carved figures and flower and geometric ornament, standing at village entrances, crossroads, cemeteries and shrines. Once consecrated by a priest, a cross is sacred and draws offerings — food, rosaries, scarves and aprons — seeking fertility, healing or protection, and the craft's masters, the kryždirbiai, shape stogastulpiai, koplytstulpiai and full crosses in styles that vary from region to region. Under Russian imperial rule and again under the Soviet occupation the wayside cross became a symbol of national identity, and in 2001 the tradition was proclaimed by UNESCO a Masterpiece of the Oral and Intangible Heritage of Humanity.",
    "lietuviska-juosta": "Hand-woven sash of linen and wool, rich with geometric patterns in several colours, worn by Lithuanian men and women wrapped at the waist over festive dress and given as gifts at weddings, christenings and funerals. The juosta was woven on narrow looms or by tablet weaving, and every region knew its own ornament — rhombuses, zigzags, crosses and small stars — so that a sash could name the wearer's parish. In folk belief the sash was protective: it binds, fastens and marks a sacred boundary, and a woven band given away could carry goodwill or serve as an offering, mediating between people and the spirits of field and forest.",
    "verbos-easter-palms": "Tall bouquets of dried and dyed grasses, flowers, mosses, juniper and willow, bound with leaves and seeds onto a rod of hazel or willow, carried to church on Palm Sunday for consecration and kept afterwards in an honoured place at home. The verba tradition has been practised for at least seven generations in villages northwest of Vilnius and is documented in paintings and ethnographies since the mid-1800s, and the palms are still made for Palm Sunday, for Easter and for the St. Casimir's Fair in Vilnius each March. The consecrated verba is kept by the household as a protection against storms and misfortune, hung behind the door or on the wall through the year.",
    "kankles": "Archaic Lithuanian plucked box zither, a trapezoid of solid wood — maple, linden or ash — hollowed from a single piece and strung with parallel strings, of the same Baltic psaltery family as the Latvian kokle and the Estonian kannel. Old belief held that the bards, the vaidilos, sang heroic songs and served the gods to its music, and that the best instrument wood was cut between a person's death and funeral, for a mourned tree lent the kanklės a sorrowful, spirit-voiced tone. The instrument accompanied wedding songs and dances, its players, the kanklininkai, being honoured guests, and it was revived in the twentieth-century folk revival as a national instrument.",
    "egles-dress": "In the Lithuanian tale 'Eglė the Queen of Serpents', the garment Eglė wore when she bathed at the lake: a coiled grass snake slipped into her sleeve and would return her clothing only if she promised to marry its king. That pledged dress drives the whole tale — the serpent bridegroom, nine years lived beneath the sea, three impossible tasks set for her children — and at the end Eglė, refusing to follow her transformed husband's cruelty, is changed into a spruce tree, while her children become the oak, ash and birch of the Lithuanian forest. The dress is the object that binds the human and the serpent world in one of the best-loved tales of the Baltic.",
    "lielvarde-belt": "The Lielvārde belt: a wide woven wool sash of red-and-white geometric patterns, with small figures worked into the bands, worn with Latvian folk costume and woven in the Lielvārde region of central Latvia. Folklore remembers it as a protective band that warded off evil, and since the 1970s the repeating patterns have been read by some as a hidden code of the universe — even of human DNA — a theory championed in popular writing though not by all scholars. The folklorist Janīna Kursīte traces its red-white symbolism to ancient protective clothing and incantations, and the belt was admitted to the Latvian Cultural Canon in 2008 as a national symbol.",
    "sakta": "The sakta, the ancient Baltic breast brooch of bronze, silver or silver-gilt, fastened the folk costume — above all the bride's — at throat or chest, in one or several at once. Archaeological finds date the fibula type back roughly two millennia, and the later 'bubble' saktas, with hemispherical bosses set with glass studs, were trusted as a woman's savings, pinned to her dress as a portable store of value. A Latvian folk song says the goddess Laima makes fibulae for a girl, 'immersing them in silver', and the brooch was given at the coming-of-age ceremonies of girls and kept as an heirloom of the family.",
    "kokle": "The Latvian plucked box zither: a trapezoid soundbox with parallel strings over a flat board, carved from maple, ash or lime, played by strumming and plucking. A chronicle entry of 1225, when Henricus de Lettis wrote of a kokle played by Livonian youths, makes it the oldest documented psaltery in Europe, and Latvian folk songs call its strings 'silver war' and 'golden war'. The kokle accompanied the dainas, the great corpus of Latvian folksong, and in the twentieth century a larger concert kokle was developed; in 2008 the kokle and the art of koklēšana were placed in the Latvian Cultural Canon as the national instrument.",
    "laimas-distaff": "The distaff of fate in Latvian and Lithuanian belief: a carved spindle-holder on which the goddess Laima, or the forest fairy Lauma, spins and measures the thread of a human life, fixing its length and its luck. Folk accounts describe laumas borrowing distaffs and spindles from village women and spinning linen by night, and the spindle's turning thread stands in countless spinning dainas for fate being spun out for a newborn child. The distaff itself was a treasured, often carved and painted object passed from mother to daughter, so that the homely tool of flax-spinning carried a double meaning: the thread of cloth and the thread of destiny.",
    "jani-wreath": "The midsummer wreath of Jāņi: for women and girls, plaited from flowers, grasses, herbs and leaves, a braid of twenty-seven plants being held to ward off disasters, disease and enemies, while men and boys wore rings of oak leaves as tokens of strength. Worn through Līgo night on 23 June with singing, cheese, beer and bonfire jumping, the wreath is kept afterwards — hung in the house, given to the cattle or laid under the pillow — for protection and healing through the year. The customs, described since the seventeenth century, make the wreath the visible emblem of the great festival of the Latvian summer solstice.",
    "estonian-kannel": "Estonia's plucked box zither, a small winged or trapezoid instrument carved from a single piece of wood and strung with wire or gut strings, played to accompany regilaul, the ancient runic-song tradition shared with Finland's kantele and Lithuania's kanklės. Folk songs and folk archaeology place the kannel in Baltic-Finnic music for well over a thousand years, and the instrument was long the companion of song and dance in the village. It survives and flourishes in the folk revival, where ensembles play both the small historical kannel and enlarged chromatic versions, keeping the oldest instrument of Estonian music on the concert stage.",
    "seto-costume": "The Seto women's folk costume of south-eastern Estonia's Setomaa: a striking white, black and red ensemble of striped or checked skirt, linen blouse, woven belt and heavy silver jewellery, above all the large seto silver brooch with its coin pendants. The costume is integral to leelo, the polyphonic singing tradition inscribed by UNESCO in 2009, for the Seto choir sang in traditional dress, and it is worn for church feasts, weddings and Seto Kingdom Day, where it announces the wearer's village and lineage. The dress is made and passed down by Seto women, whose handicraft knowledge — of weaving, embroidery and silverwork — is as much a part of Setomaa's heritage as its songs.",
    "kihnu-skirt": "The striped woolen skirt and knitted garments of Kihnu Island's women: bright red, green and blue striped cloth woven on home looms from local wool, worn with embroidered blouses, sashes, mittens and stockings whose colours and patterns recall old legends. With the island's men long at sea, Kihnu's women carried the culture of the island, and the making of these garments — together with the songs, dances and handicraft skills of the Kihnu cultural space inscribed by UNESCO in 2003 — became an emblem of Estonian island identity. The striped skirt, folded and held by a woven belt, is still worn daily by older women and with pride at festivals.",
    "kirivoo": "The kirivöö, the Estonian pick-up patterned belt: a narrow woven band of wool over a linen or wool ground, carrying rows of small crosses, rhombuses, triangles and diagonal figures worked by the pick-up technique. Each parish knew its own edge patterns, so that the belt could tell where a woman came from, and the belts were worn wrapped at the waist with folk dress, and given as gifts, love-pledges and protective charms. The Estonian National Museum holds belts from across the country, and studies of the small patterns at the belt edges continue to map the regional styles and their meanings.",
    "pohjanael": "The Põhjanael, the 'North Nail', the Estonian folk name for the North Star: in the old Baltic-Finnic worldview the sky was an upturned cauldron or great wheel turning on a nail driven through its centre, and that nail is Polaris. Farmers read the seasons from the stars turning around it, and folk sayings spoke of the sky-wheel's spokes and of the nail that holds the heavens fixed. The folklorist Matthias Johann Eisen recorded the motif in his 'Eesti Mütoloogia' and folk-astronomy notes, preserving a sky-picture in which the fixed North Star is the axle of the whole turning world.",
}

inp = json.load(open(SRC, encoding='utf-8'))
out = []
for it in inp:
    item = dict(it)
    slug = item['slug']
    if slug not in D:
        raise SystemExit(f'no expansion for {slug}')
    item['description'] = D[slug]
    out.append(item)

with open(DST, 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
    f.write('\n')

for it in out:
    print(f"{it['slug']}: {len(it['description'])} chars")
print('written', len(out), 'items')
